import{b as a,O as e,g as r,j as o}from"./chunks/framework.DcaUmd3X.js";const p=JSON.parse('{"title":"性能测试报告指标解读：这些指标到底在说什么","description":"","frontmatter":{"tags":["性能测试","指标","压测"]},"headers":[],"relativePath":"blog/performance-testing/performance-report-metrics/index.md","filePath":"个人博客/性能测试/1.性能测试报告指标解读.md","lastUpdated":1787474824000}'),d={name:"blog/performance-testing/performance-report-metrics/index.md"};function s(l,t,i,n,h,u){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="性能测试报告指标解读-这些指标到底在说什么" tabindex="-1">性能测试报告指标解读：这些指标到底在说什么 <a class="header-anchor" href="#性能测试报告指标解读-这些指标到底在说什么" aria-label="Permalink to &quot;性能测试报告指标解读：这些指标到底在说什么&quot;">​</a></h1><p>记录一下之前给某管理系统做的一次性能压测，目的是摸清服务器在多少并发下会顶不住。报告出来了，但里面的指标——90% 用户、95% 用户、吞吐量、CPU 负载、I/O……第一次接触的人很容易看得云里雾里。这篇就把这份报告里的每个参数讲明白，再拿真实数据对号入座。</p><h2 id="测试是怎么设计的" tabindex="-1">测试是怎么设计的 <a class="header-anchor" href="#测试是怎么设计的" aria-label="Permalink to &quot;测试是怎么设计的&quot;">​</a></h2><p>先交代背景：这是一个典型的管理类业务系统，核心操作包括表单保存、批量录入、导出、打印标签、批量签名等。为了找瓶颈，按 20、50、100、200 四个并发档位逐步加压，每档跑 10 分钟，统计响应时间和成功率。</p><p>被测的 7 个接口：</p><table tabindex="0"><thead><tr><th>接口</th><th>业务含义</th></tr></thead><tbody><tr><td>接口 A</td><td>表单保存（生成编号）</td></tr><tr><td>接口 B</td><td>表单保存（生成计划、数据同步）</td></tr><tr><td>接口 C</td><td>批量录入</td></tr><tr><td>接口 D</td><td>导出报表</td></tr><tr><td>接口 E</td><td>打印标签</td></tr><tr><td>接口 F</td><td>批量签名</td></tr><tr><td>接口 G</td><td>批量撤销签名</td></tr></tbody></table><h2 id="指标逐个拆解" tabindex="-1">指标逐个拆解 <a class="header-anchor" href="#指标逐个拆解" aria-label="Permalink to &quot;指标逐个拆解&quot;">​</a></h2><h3 id="_1-响应时间四件套-最小值-最大值-90-95" tabindex="-1">1. 响应时间四件套：最小值 / 最大值 / 90% / 95% <a class="header-anchor" href="#_1-响应时间四件套-最小值-最大值-90-95" aria-label="Permalink to &quot;1. 响应时间四件套：最小值 / 最大值 / 90% / 95%&quot;">​</a></h3><p>这是报告里最核心的一组数，单位都是毫秒（ms）。</p><ul><li><strong>最小值</strong>：所有请求里最快的那一次。它代表系统的&quot;最佳表现&quot;，理论上限。</li><li><strong>最大值</strong>：最慢的那一次。它代表&quot;最坏情况&quot;，但有一个坑——最大值很容易被一两个异常请求带偏。比如某次网络抖动把一次请求拖到 10 秒，最大值就变成 10000ms，但 99% 的用户根本没受影响。</li><li><strong>90% 用户（P90）</strong>：把这次压测的所有请求按耗时从小到大排好队，取排在第 90% 位置的那个值。含义是：<strong>90% 的请求都在这个时间内完成</strong>。</li><li><strong>95% 用户（P95）</strong>：同理，取第 95% 位置，比 P90 更严格，<strong>95% 的请求都在这个时间内完成</strong>。</li></ul><p>为什么报告不用&quot;平均响应时间&quot;？因为平均值会被长尾请求拉高，掩盖大多数人的真实体验。举个夸张的例子：100 个请求里 99 个都是 100ms，1 个卡了 10 秒，平均值是 199ms，但 P90 只有 100ms——99% 的用户体感其实是 100ms，平均值的 199ms 反而骗了你。所以<strong>分位数（P90/P95）比平均值更能反映真实用户体感</strong>。</p><h3 id="_2-错误率" tabindex="-1">2. 错误率 <a class="header-anchor" href="#_2-错误率" aria-label="Permalink to &quot;2. 错误率&quot;">​</a></h3><p>错误率 = 失败请求数 / 总请求数。这份报告四个档位全部是 0.00%，说明整个压测过程中没有出现超时、5xx、连接失败这类错误。错误率是压测里比响应时间更硬的指标：<strong>响应慢还只是体验问题，报错就是功能不可用了</strong>，错误率必须优先看。</p><h3 id="_3-吞吐量-request-sec" tabindex="-1">3. 吞吐量（request/sec） <a class="header-anchor" href="#_3-吞吐量-request-sec" aria-label="Permalink to &quot;3. 吞吐量（request/sec）&quot;">​</a></h3><p>吞吐量 = 每秒系统处理的请求数，单位 request/sec。它回答的是&quot;这台服务器一秒能扛多少活&quot;。</p><p>注意它和并发数不是一回事：并发是&quot;同时有多少用户在等&quot;，吞吐量是&quot;一秒实际完成了多少&quot;。两者通过响应时间关联，大致满足：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>吞吐量 ≈ 并发数 / 平均响应时间</span></span></code></pre></div><p>拿报告里 200 并发那档验证：吞吐量 87.69 req/s，反推平均响应时间 ≈ 200 / 87.69 ≈ 2.28 秒，跟实测 P90 的 2.5 秒量级对得上。</p><h3 id="_4-每秒接收数据量-kb-sec" tabindex="-1">4. 每秒接收数据量（kb/sec） <a class="header-anchor" href="#_4-每秒接收数据量-kb-sec" aria-label="Permalink to &quot;4. 每秒接收数据量（kb/sec）&quot;">​</a></h3><p>这是网络维度的指标：服务器每秒吐给客户端多少数据（下行带宽占用）。报告里 200 并发时是 249.25 kb/s，配合 50M 带宽的服务器完全不是瓶颈。它主要用来判断<strong>是不是网络先扛不住，而不是 CPU/内存先扛不住</strong>。</p><h3 id="_5-服务器资源指标-cpu-占用率-cpu-负载-i-o" tabindex="-1">5. 服务器资源指标：CPU 占用率 / CPU 负载 / I/O <a class="header-anchor" href="#_5-服务器资源指标-cpu-占用率-cpu-负载-i-o" aria-label="Permalink to &quot;5. 服务器资源指标：CPU 占用率 / CPU 负载 / I/O&quot;">​</a></h3><p>报告最后还关注了服务器本身的健康状况：</p><ul><li><strong>CPU 占用率</strong>：CPU 忙的比例，直观但只反映&quot;此刻&quot;。</li><li><strong>CPU 负载（load average）</strong>：排队等 CPU 的任务数。一台 4 核机器，负载 ≤ 4 说明 CPU 基本够用；持续 &gt; 4 说明有任务在排队了。<strong>负载比占用率更能反映&quot;过载&quot;</strong>，因为占用率 100% 但没排队其实还能扛，负载飙高才是真瓶颈。</li><li><strong>I/O used / I/O bytes</strong>：磁盘读写忙不忙、吞吐多少。数据库类系统很看这个，磁盘一旦是瓶颈，CPU 再空也没用。</li></ul><blockquote><p>说明：这份报告的资源占用曲线（CPU/负载/I/O）是以图片形式呈现的，本次转换未包含图片，所以下面的分析只基于文本里的响应时间、吞吐量、错误率三个维度。</p></blockquote><h3 id="_6-思考时间" tabindex="-1">6. 思考时间 <a class="header-anchor" href="#_6-思考时间" aria-label="Permalink to &quot;6. 思考时间&quot;">​</a></h3><p>报告里每个场景都标了&quot;思考时间：无&quot;。思考时间（think time）指真实用户两次操作之间的停顿（读页面、想事情）。真实压测里要不要加思考时间很关键：<strong>加了思考时间，模拟的是&quot;人在慢慢用&quot;；不加，模拟的是&quot;机器在狂刷&quot;</strong>，后者对系统的压力更狠。这份报告选择&quot;无&quot;，等于用最保守（压力最大）的口径测，能扛住说明余量更足。</p><h2 id="拿真实数据对号入座" tabindex="-1">拿真实数据对号入座 <a class="header-anchor" href="#拿真实数据对号入座" aria-label="Permalink to &quot;拿真实数据对号入座&quot;">​</a></h2><p>四个场景的汇总数据（TOTAL 行）：</p><table tabindex="0"><thead><tr><th>场景</th><th>并发</th><th>90%响应(ms)</th><th>95%响应(ms)</th><th>最大值(ms)</th><th>错误率</th><th>吞吐量(req/s)</th></tr></thead><tbody><tr><td>场景一</td><td>20</td><td>709</td><td>858</td><td>1262</td><td>0%</td><td>0.68</td></tr><tr><td>场景二</td><td>50</td><td>1068</td><td>1284</td><td>3121</td><td>0%</td><td>2.17</td></tr><tr><td>场景三</td><td>100</td><td>4222</td><td>5890</td><td>8520</td><td>0%</td><td>43.36</td></tr><tr><td>场景四</td><td>200</td><td>2534</td><td>2925</td><td>7373</td><td>0%</td><td>87.69</td></tr></tbody></table><h2 id="我的测试结果与分析" tabindex="-1">我的测试结果与分析 <a class="header-anchor" href="#我的测试结果与分析" aria-label="Permalink to &quot;我的测试结果与分析&quot;">​</a></h2><p>不看现成结论，单从上面这组过程数据，自己能推出四件事。</p><h3 id="_1-功能稳定性-全程零报错" tabindex="-1">1. 功能稳定性：全程零报错 <a class="header-anchor" href="#_1-功能稳定性-全程零报错" aria-label="Permalink to &quot;1. 功能稳定性：全程零报错&quot;">​</a></h3><p>错误率四个档位全是 0.00%，说明在 20~200 并发范围内，7 个核心接口没有出现超时、5xx、连接失败。单看这一条，系统在 200 并发下是&quot;能用&quot;的。</p><h3 id="_2-容量-200-并发还没摸到天花板" tabindex="-1">2. 容量：200 并发还没摸到天花板 <a class="header-anchor" href="#_2-容量-200-并发还没摸到天花板" aria-label="Permalink to &quot;2. 容量：200 并发还没摸到天花板&quot;">​</a></h3><p>吞吐量从 20 并发的 0.68 一路涨到 200 并发的 87.69 req/s。关键看 100→200 这一段：并发翻倍（100→200），吞吐量也从 43.36 翻到 87.69，几乎是线性增长。这说明系统还没到吞吐拐点——如果已经到瓶颈，并发再往上加，吞吐量会走平甚至下跌。所以 200 并发不是上限，实际容量还有余量。</p><h3 id="_3-响应时间-200-并发约-3-秒-处于可接受区间" tabindex="-1">3. 响应时间：200 并发约 3 秒，处于可接受区间 <a class="header-anchor" href="#_3-响应时间-200-并发约-3-秒-处于可接受区间" aria-label="Permalink to &quot;3. 响应时间：200 并发约 3 秒，处于可接受区间&quot;">​</a></h3><p>拿 200 并发档看，P90 2534ms、P95 2925ms，也就是 95% 的请求在 3 秒内完成。对一个含导出、打印这类重操作的业务系统，3 秒内完成绝大多数请求算达标。若业务对导出接口有更严要求，要单独看「接口 D（导出报表）」——它的 P95 是 3826ms，是七个接口里最慢的一项，需要单点关注。</p><h3 id="_4-两个数据异常点-建议重测后再下最终结论" tabindex="-1">4. 两个数据异常点，建议重测后再下最终结论 <a class="header-anchor" href="#_4-两个数据异常点-建议重测后再下最终结论" aria-label="Permalink to &quot;4. 两个数据异常点，建议重测后再下最终结论&quot;">​</a></h3><p>这组数据里有两处反常识的地方，我更倾向于先归为&quot;压测数据问题&quot;，而不是&quot;系统问题&quot;：</p><ul><li><strong>50 并发档吞吐量异常偏低</strong>：只有 2.17 req/s。50 并发、P95 才 1.28 秒，理论上吞吐量应该在 50 / 1.28 ≈ 39 req/s 的量级，实测却只有 2.17，差了近 20 倍。而且它前后的 20 档（0.68）和 100 档（43.36）是连贯的，唯独 50 档断崖。这更像那一轮压测没打满（脚本节流、并发没真正起来），而不是系统真实容量。</li><li><strong>100 并发档响应时间异常偏高</strong>：P95 5890ms，反而比 200 并发的 2925ms 还慢。拆开看是「接口 D（导出报表）」一项拖累（P95 6963ms、最大 8520ms），而它在 200 并发档反而回落到 3826ms。并发更高反而更快，不合常理，大概率是那一轮环境波动、数据量差异，或撞上垃圾回收/缓存失效。</li></ul><p>这两个点直接关系到最后能不能放心下&quot;200 并发达标&quot;的结论。稳妥的做法是：<strong>50 并发和 100 并发两档重测一次</strong>，确认异常是压测执行的问题，还是系统真有隐性瓶颈。</p><h2 id="给新人的读报告-checklist" tabindex="-1">给新人的读报告 checklist <a class="header-anchor" href="#给新人的读报告-checklist" aria-label="Permalink to &quot;给新人的读报告 checklist&quot;">​</a></h2><p>拿到一份性能测试报告，按这个顺序看不容易被带偏：</p><ol><li><strong>先看错误率</strong>——非 0 就先去查为什么，别的都先放一边</li><li><strong>再看 P90/P95</strong>——别信平均值，长尾会骗人</li><li><strong>看吞吐量</strong>——判断系统容量够不够</li><li><strong>对照资源指标</strong>——CPU 负载、I/O 是不是已经顶到天花板</li><li><strong>留意反常数据点</strong>——像 50 档吞吐断崖、100 档响应倒挂这种，要么是环境问题，要么藏着真问题</li></ol>',44)])])}const q=a(d,[["render",s]]);export{p as __pageData,q as default};
